// ───────────── Interpretación de la respuesta (sin IA) ─────────────
const INJECTION = /(ignore|disregard|forget) (all |any |your |the )?(previous|prior|above|earlier)?\s*(instructions|rules|prompt)|system prompt|you are now|<\/?(system|assistant)>/i;

