  if (word === 'cancel') return { kind: 'cancel', reasons: [] };
  const slots = eligibleSlots(freeSlots, appointment, now, cfg);
  return slots.length ? { kind: 'offer_slots', slots, reasons: [] } : handoff('no_slots');
