// ───────────── No-show ─────────────
function noShowCandidates(appts, now, cfg) {
  return appts.filter(a => ACTIVE.includes(a.status) && !a.checked_in_at && mins(now, a.starts_at) >= cfg.graceMin && mins(now, a.starts_at) <= cfg.lookbackHours * 60);
