// ───────────── Personal ─────────────
function applyStaffUpdate(appt, update, now) {
  const fail = error => ({ ok: false, error });
  if (!appt) return fail('appointment_not_found');
  const done = (outcome, set, event) => ({ ok: true, outcome, set, event });
